package main

const quotaPageHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>OpenCode Go Pool</title>
<style>
:root{color-scheme:dark;--ink:#edf7f1;--muted:#8fa198;--panel:#151b18;--panel-2:#1b2420;--line:#2e3a34;--mint:#72e0aa;--mint-deep:#183b2b;--coral:#ff8f72;--amber:#e5bd69;--shadow:0 18px 50px #0005;font:14px/1.45 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#0c110f;color:var(--ink)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 84% -10%,#254d3a66,transparent 34%),#0c110f}button,input,textarea,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--mint);outline-offset:2px}main{max-width:1240px;margin:auto;padding:28px}.mast{display:grid;grid-template-columns:1fr auto;gap:24px;align-items:end;padding:10px 0 22px;border-bottom:1px solid var(--line)}.eyebrow{font:800 11px/1 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.17em;text-transform:uppercase;color:var(--mint)}h1{font-size:clamp(34px,6vw,64px);line-height:.96;letter-spacing:-.055em;margin:12px 0 8px;max-width:720px}.lede{margin:0;color:var(--muted);max-width:650px}.route-note{max-width:330px;padding:14px 16px;border:1px solid #37604b;background:#122019;color:#b9d8c8}.route-note strong{display:block;color:var(--mint);margin-bottom:3px}.toolbar{display:grid;grid-template-columns:minmax(180px,1fr) auto auto;gap:10px;margin:22px 0 12px}.field,.select,.area{width:100%;border:1px solid var(--line);border-radius:8px;background:#111714;color:var(--ink);padding:10px 12px}.area{min-height:78px;resize:vertical}.button{border:1px solid #416251;border-radius:8px;padding:10px 14px;background:#1b2a22;color:var(--ink);font-weight:750}.button:hover{border-color:var(--mint)}.button:disabled{opacity:.42;cursor:not-allowed;border-color:var(--line)}.button.primary{background:var(--mint);border-color:var(--mint);color:#102018}.button.danger{border-color:#754238;background:#2a1916;color:#ffb09b}.button.ghost{background:transparent}.status{min-height:22px;color:var(--muted);margin:8px 0}.status.error{color:var(--coral)}.summary{display:flex;gap:18px;flex-wrap:wrap;padding:13px 0 18px;color:var(--muted);font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.summary b{color:var(--ink)}.accounts{display:grid;gap:12px}.card{display:grid;grid-template-columns:minmax(250px,1.05fr) minmax(360px,1.5fr) auto;gap:18px;align-items:stretch;border:1px solid var(--line);background:linear-gradient(135deg,var(--panel),#121714);border-radius:12px;overflow:hidden;box-shadow:0 8px 24px #0002}.identity{padding:18px;border-right:1px solid var(--line)}.identity-top{display:flex;align-items:center;gap:9px;min-width:0}.dot{width:9px;height:9px;border-radius:50%;background:var(--muted);box-shadow:0 0 0 4px #ffffff0a}.dot.healthy{background:var(--mint)}.dot.unavailable,.dot.disabled{background:var(--amber)}.dot.error{background:var(--coral)}.label{font-size:20px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.email{margin:5px 0;color:#b6c5bd;word-break:break-all}.technical{font:11px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;color:#72837a}.secrets{display:grid;gap:7px;margin-top:14px}.secret-row{display:grid;grid-template-columns:66px minmax(0,1fr) auto;gap:8px;align-items:center}.secret-label{color:var(--muted);font-size:12px}.secret-value{font:12px/1.35 ui-monospace,SFMono-Regular,Consolas,monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mini{border:1px solid var(--line);background:#111714;color:#bfd0c7;border-radius:6px;padding:5px 8px;font-size:12px}.links{display:flex;gap:8px;row-gap:10px;align-items:center;flex-wrap:wrap;margin-top:12px}.links a{color:var(--mint);text-decoration:none;border-bottom:1px solid #72e0aa66}.links .pill{margin-top:0}.quota{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:18px}.meter{display:grid;align-content:center;gap:8px}.meter-head{display:flex;justify-content:space-between;gap:8px;font:12px/1 ui-monospace,SFMono-Regular,Consolas,monospace}.meter-head span:first-child{color:var(--muted)}.track{height:8px;border-radius:99px;background:#26312c;overflow:hidden}.fill{height:100%;width:0;background:linear-gradient(90deg,var(--mint),#b8ffd9);border-radius:inherit}.fill.warn{background:linear-gradient(90deg,var(--amber),#ffe09b)}.fill.hot{background:linear-gradient(90deg,var(--coral),#ffbea9)}.reset{color:#718178;font-size:11px}.actions{min-width:132px;padding:14px;display:grid;align-content:center;gap:8px;border-left:1px solid var(--line);background:#101512}.actions .button{width:100%;padding:8px 10px}.pill{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:99px;padding:3px 8px;font:11px/1.2 ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--muted);margin-top:9px}.empty{padding:54px 22px;text-align:center;border:1px dashed #405049;border-radius:12px;color:var(--muted)}.hidden{display:none!important}.modal{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:#050806cc;backdrop-filter:blur(8px)}.dialog{width:min(760px,100%);max-height:92vh;overflow:auto;border:1px solid #415349;border-radius:14px;background:#111714;box-shadow:var(--shadow)}.dialog-head{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:18px 20px;border-bottom:1px solid var(--line)}.dialog-head h2{margin:0;font-size:23px}.dialog-body{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px}.group{display:grid;gap:6px}.group.wide{grid-column:1/-1}.group label{color:var(--muted);font-size:12px}.check{display:flex;align-items:center;gap:8px}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;padding:16px 20px;border-top:1px solid var(--line)}.toast{position:fixed;right:18px;bottom:18px;z-index:20;padding:11px 14px;border:1px solid #3e6a52;border-radius:8px;background:#14241b;color:#cffff0;box-shadow:var(--shadow)}@media(max-width:900px){.mast{grid-template-columns:1fr}.route-note{max-width:none}.card{grid-template-columns:1fr}.identity,.actions{border:0}.identity{border-bottom:1px solid var(--line)}.actions{grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line)}.quota{padding-top:6px}}@media(max-width:620px){main{padding:18px}.toolbar{grid-template-columns:1fr 1fr}.toolbar .field{grid-column:1/-1}.quota{grid-template-columns:1fr}.actions{grid-template-columns:1fr}.dialog-body{grid-template-columns:1fr}.group.wide{grid-column:auto}}@media(prefers-reduced-motion:no-preference){.card{transition:transform .16s ease,border-color .16s ease}.card:hover{transform:translateY(-2px);border-color:#466252}}
</style>
</head>
<body>
<main>
<header class="mast">
<div><div class="eyebrow">Account switchboard</div><h1>OpenCode Go Pool</h1><p class="lede">Know every account by name. Check quota, track referral relationships, and move keys in or out of CLIProxy without another login.</p></div>
<aside class="route-note"><strong>Routing reality</strong>Round-robin selects new sessions. Session affinity keeps each session on its account for one hour.</aside>
</header>
<div class="toolbar"><input class="field" id="search" type="search" placeholder="Search label, email, provider, or note"><button class="button primary" type="button" id="add">Add account</button><button class="button" type="button" id="refresh">Refresh</button></div>
<div class="status" id="status">Loading the Management Center session…</div>
<div class="summary hidden" id="summary"></div>
<section class="accounts hidden" id="accounts" aria-label="OpenCode Go accounts"></section>
<div class="empty hidden" id="empty">No accounts match this view.</div>
</main>
<div class="modal hidden" id="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title">
<div class="dialog">
<div class="dialog-head"><h2 id="dialog-title">Add account</h2><button class="mini" type="button" id="close">Close</button></div>
<div class="dialog-body">
<div class="group wide"><label for="account-key">API key</label><input class="field" id="account-key" type="password" autocomplete="off"></div>
<div class="group"><label for="account-label">Label</label><input class="field" id="account-label" placeholder="go-01"></div>
<div class="group"><label for="account-provider">CLIProxy provider</label><select class="select" id="account-provider"></select></div>
<div class="group"><label for="account-email">Email</label><input class="field" id="account-email" type="email"></div>
<div class="group"><label for="account-password">Password</label><input class="field" id="account-password" type="password" autocomplete="off"></div>
<div class="group wide"><label for="account-referral">Referral URL</label><input class="field" id="account-referral" type="url" placeholder="https://opencode.ai/go?ref=..."></div>
<div class="group wide"><label for="account-referred-by">Referred by account</label><select class="select" id="account-referred-by"><option value="">Direct signup</option></select></div>
<div class="group"><label for="account-expires">Expires</label><input class="field" id="account-expires" type="date"></div>
<div class="group wide"><label for="account-notes">Notes</label><textarea class="area" id="account-notes"></textarea></div>
</div>
<div class="dialog-actions"><button class="button ghost" type="button" id="cancel">Cancel</button><button class="button primary" type="button" id="save">Save account</button></div>
</div>
</div>
<div class="toast hidden" id="toast"></div>
<script>
(()=>{
const AUTH_KEY='cli-proxy-auth',PREFIX='enc::v1::',SALT='cli-proxy-api-webui::secure-storage',ACCOUNTS_API='/v0/management/plugins/opencode-go-quota/accounts',PROVIDERS_API='/v0/management/openai-compatibility';
const el=id=>document.getElementById(id),status=el('status'),list=el('accounts'),empty=el('empty'),summary=el('summary'),modal=el('modal'),toast=el('toast');let key='',revision='',accounts=[],providers=[],eligibleProviders=[],editing=-1;
function decode(raw){if(!raw)return'';if(!raw.startsWith(PREFIX))return raw;const data=Uint8Array.from(atob(raw.slice(PREFIX.length)),c=>c.charCodeAt(0)),seed=new TextEncoder().encode(SALT+'|'+location.host+'|'+navigator.userAgent),out=new Uint8Array(data.length);for(let i=0;i<data.length;i++)out[i]=data[i]^seed[i%seed.length];return new TextDecoder().decode(out)}
function managementKey(){for(const name of [AUTH_KEY,'managementKey']){try{const parsed=JSON.parse(decode(localStorage.getItem(name))),value=parsed?.state?.managementKey??parsed?.managementKey??parsed;if(typeof value==='string'&&value)return value}catch{}}return''}
async function request(url,options={}){const headers={Authorization:'Bearer '+key,Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{})};const response=await fetch(url,{...options,headers:{...headers,...options.headers},cache:'no-store'});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||('HTTP '+response.status));return data}
const text=(tag,value,cls)=>{const node=document.createElement(tag);node.textContent=value??'';if(cls)node.className=cls;return node};
const safeURL=value=>{try{const url=new URL(value);return url.protocol==='http:'||url.protocol==='https:'?url.href:''}catch{return''}};
const masked=value=>value?value.slice(0,5)+'…'+value.slice(-5):'Not recorded';
const accountName=account=>account?.label||account?.email||account?.key_id||'Unlabelled account';
const accountOptionName=account=>[account?.label,account?.email].filter(Boolean).join(' · ')||account?.key_id||'Unlabelled account';
const fmtReset=window=>window?.resetsAt?new Date(window.resetsAt).toLocaleString():'No reset data';
function flash(message){toast.textContent=message;toast.classList.remove('hidden');setTimeout(()=>toast.classList.add('hidden'),1800)}
function secretRow(label,value,reveal=false){const row=text('div','', 'secret-row'),name=text('span',label,'secret-label'),shown=text('span',reveal&&value?masked(value):(value||'Not recorded'),'secret-value'),copy=text('button','Copy','mini');copy.type='button';copy.disabled=!value;copy.onclick=async()=>{await navigator.clipboard.writeText(value);flash(label+' copied')};row.append(name,shown,copy);if(reveal&&value){shown.title='Click to reveal';shown.style.cursor='pointer';shown.onclick=()=>{shown.textContent=shown.textContent===value?masked(value):value}}return row}
function meter(name,window){const percent=Number.isFinite(window?.percent)?Math.max(0,Math.min(100,window.percent)):0,box=text('div','', 'meter'),head=text('div','', 'meter-head'),track=text('div','', 'track'),fill=text('div','', 'fill'+(percent>=90?' hot':percent>=70?' warn':''));head.append(text('span',name),text('b',window&&Number.isFinite(window.percent)?window.percent+'%':'—'));fill.style.width=percent+'%';track.append(fill);box.append(head,track,text('div',fmtReset(window),'reset'));return box}
function link(label,value){const href=safeURL(value);if(!href)return null;const a=text('a',label);a.href=href;a.target='_blank';a.rel='noreferrer';return a}
function render(){const add=el('add');add.disabled=openCodeProviders().length===0;add.title=add.disabled?'No eligible OpenCode provider configured':'';const query=el('search').value.trim().toLowerCase(),visible=accounts.filter(account=>[account.label,account.email,account.provider_name,account.notes,account.key_id].some(value=>String(value||'').toLowerCase().includes(query)));list.replaceChildren();const enabled=accounts.filter(a=>a.pool_enabled).length,healthy=accounts.filter(a=>a.status==='healthy').length;summary.replaceChildren();for(const [value,labelText] of [[accounts.length,'accounts'],[enabled,'enabled'],[healthy,'healthy']]){const span=text('span',''),bold=text('b',String(value));span.append(bold,document.createTextNode(' '+labelText));summary.append(span)};summary.classList.remove('hidden');for(const account of visible){const card=text('article','', 'card'),identity=text('div','', 'identity'),top=text('div','', 'identity-top'),dot=text('span','', 'dot '+(account.status||'disabled')),label=text('div',account.label||account.email||account.key_id||'Unlabelled account','label');top.append(dot,label);identity.append(top,text('div',account.email||'Email not recorded','email'),text('div',(account.provider_name||'No provider')+' · '+(account.key_id||'not in pool'),'technical'));const secrets=text('div','', 'secrets');secrets.append(secretRow('API key',account.api_key,true),secretRow('Password',account.password,true));identity.append(secrets);const links=text('div','', 'links'),ref=link('Referral',account.referral_url);if(ref)links.append(ref);if(account.referred_by_api_key){const parent=accounts.find(candidate=>candidate.api_key===account.referred_by_api_key);links.append(text('span','Referred by '+accountName(parent),'pill'))}if(account.expires_at)links.append(text('span','Expires '+account.expires_at,'pill'));if(links.childNodes.length)identity.append(links);if(account.notes)identity.append(text('div',account.notes,'pill'));const usage=account.usage||{},quota=text('div','', 'quota');quota.append(meter('5h',usage.rolling),meter('Weekly',usage.weekly),meter('Monthly',usage.monthly));const actions=text('div','', 'actions'),toggle=text('button',account.pool_enabled?'Disable':'Enable','button'),edit=text('button','Edit','button ghost'),remove=text('button','Delete','button danger');toggle.type=edit.type=remove.type='button';toggle.onclick=()=>togglePool(account,!account.pool_enabled);edit.onclick=()=>openEditor(account,accounts.indexOf(account));remove.disabled=account.pool_enabled;remove.title=account.pool_enabled?'Disable account before deleting it':'';remove.onclick=()=>removeAccount(account);actions.append(toggle,edit,remove);card.append(identity,quota,actions);list.append(card)}list.classList.toggle('hidden',visible.length===0);empty.classList.toggle('hidden',visible.length!==0)}
function openEditor(account,index){editing=index;el('dialog-title').textContent=index<0?'Add account':'Edit account';const value=account||{};el('account-key').value=value.api_key||'';el('account-key').disabled=index>=0;el('account-label').value=value.label||'';el('account-email').value=value.email||'';el('account-password').value=value.password||'';el('account-referral').value=value.referral_url||'';el('account-expires').value=value.expires_at||'';el('account-notes').value=value.notes||'';const select=el('account-provider');select.replaceChildren();select.disabled=index>=0;for(const provider of openCodeProviders()){const option=text('option',provider.name);option.value=provider.name;select.append(option)}if(value.provider_name)select.value=value.provider_name;const referred=el('account-referred-by'),direct=text('option','Direct signup');direct.value='';referred.replaceChildren(direct);for(const candidate of accounts){if(candidate.api_key===value.api_key)continue;const option=text('option',accountOptionName(candidate));option.value=candidate.api_key;referred.append(option)}referred.value=value.referred_by_api_key||'';modal.classList.remove('hidden')}
function closeEditor(){modal.classList.add('hidden');editing=-1}
function openCodeProviders(){const names=new Set(eligibleProviders.map(provider=>String(provider.name||'').toLowerCase()));return providers.filter(provider=>names.has(String(provider.name||'').toLowerCase()))}
function providerFor(account){return providers.find(p=>String(p.name||'').toLowerCase()===String(account.provider_name||'').toLowerCase())}
function cleanProvider(provider,entries){const value=structuredClone(provider);value['api-key-entries']=entries.map(entry=>{const clean={...entry};delete clean['auth-index'];return clean});return value}
async function saveRegistry(next){const result=await request(ACCOUNTS_API,{method:'PUT',body:JSON.stringify({revision,accounts:next.map(({api_key,provider_name,label,email,password,referral_url,referred_by_api_key,expires_at,notes})=>({api_key,provider_name,label,email,password,referral_url,referred_by_api_key,expires_at,notes}))})});revision=result.revision}
async function setPoolEnabled(account,enabled,reload=true){const mutate=async()=>{const fresh=await request(PROVIDERS_API);providers=fresh['openai-compatibility']||[];const provider=providerFor(account);if(!provider)throw new Error('No CLIProxy provider named '+account.provider_name+' was found');const current=provider['api-key-entries']||[],index=current.findIndex(entry=>entry['api-key']===account.api_key);let entries=current;if(enabled&&index<0)entries=[...current,{'api-key':account.api_key}];if(enabled&&index>=0&&Number(current[index].weight)===0)entries=current.map((entry,i)=>i===index?{...entry,weight:1}:entry);if(!enabled&&index>=0)entries=current.filter((_,i)=>i!==index);if(entries===current)return;const value=cleanProvider(provider,entries);await request(PROVIDERS_API,{method:'PATCH',body:JSON.stringify({name:provider.name,value})});providers=providers.map(item=>item===provider?value:item)};const lockName='opencode-go-pool:'+String(account.provider_name||'').toLowerCase();if(navigator.locks&&navigator.locks.request)await navigator.locks.request(lockName,mutate);else await mutate();if(reload)await load()}
async function togglePool(account,enabled){setBusy('Updating '+(account.label||account.email||'account')+'…');try{await setPoolEnabled(account,enabled);flash(enabled?'Account enabled':'Account disabled')}catch(error){await recover(error)}finally{clearBusy()}}
async function saveAccount(){const account={api_key:el('account-key').value.trim(),provider_name:el('account-provider').value.trim(),label:el('account-label').value.trim(),email:el('account-email').value.trim(),password:el('account-password').value,referral_url:el('account-referral').value.trim(),referred_by_api_key:el('account-referred-by').value,expires_at:el('account-expires').value,notes:el('account-notes').value.trim()};if(!account.api_key||!account.provider_name){setError(new Error('API key and provider are required'));return}const current=editing>=0?accounts[editing]:null,next=accounts.map(a=>({...a}));if(editing>=0)next[editing]={...current,...account};else next.push(account);setBusy('Saving account…');try{await saveRegistry(next);closeEditor();await load();flash('Account saved. Use Enable when ready.')}catch(error){await recover(error)}finally{clearBusy()}}
async function removeAccount(account){if(account.pool_enabled){setError(new Error('Disable account before deleting it'));return}if(!confirm('Delete '+(account.label||account.email||'this account')+' from the registry?'))return;setBusy('Deleting account…');try{await saveRegistry(accounts.filter(item=>item.api_key!==account.api_key));await load();flash('Account deleted')}catch(error){await recover(error)}finally{clearBusy()}}
function setBusy(message){status.textContent=message;status.classList.remove('error')}
function clearBusy(){if(!status.classList.contains('error'))status.textContent=''}
function setError(error){status.textContent=error instanceof Error?error.message:String(error);status.classList.add('error')}
async function recover(error){try{await load()}catch{}setError(error)}
async function load(){setBusy('Checking accounts and quota…');try{const [snapshot,providerData]=await Promise.all([request(ACCOUNTS_API),request(PROVIDERS_API)]);revision=snapshot.revision;accounts=snapshot.accounts||[];eligibleProviders=snapshot.providers||[];providers=providerData['openai-compatibility']||[];render();status.textContent='Checked '+new Date(snapshot.generated_at).toLocaleString();status.classList.remove('error')}catch(error){setError(error)}}
key=managementKey();if(!key){status.textContent='Enable Remember password in Management Center, then reload this page.';status.classList.add('error');return}el('search').addEventListener('input',render);el('refresh').onclick=load;el('add').onclick=()=>openEditor(null,-1);el('close').onclick=el('cancel').onclick=closeEditor;el('save').onclick=saveAccount;modal.addEventListener('click',event=>{if(event.target===modal)closeEditor()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeEditor()});void load();
})();
</script>
</body>
</html>`
